import{_ as a,o as n,c as s,a2 as r}from"./chunks/framework.Dp0m3YJZ.js";const u=JSON.parse('{"title":"05 · FIFO 排程","description":"","frontmatter":{},"headers":[],"relativePath":"topics/scheduling.md","filePath":"topics/scheduling.md","lastUpdated":null}'),t={name:"topics/scheduling.md"};function o(c,e,i,p,d,l){return n(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="_05-·-fifo-排程" tabindex="-1">05 · FIFO 排程 <a class="header-anchor" href="#_05-·-fifo-排程" aria-label="Permalink to &quot;05 · FIFO 排程&quot;">​</a></h1><p>有了 Ready（可以執行）的行程，還要有人決定下一個用 CPU 的對象。WUWAOS 將這個選擇獨立放在 <code>kernel/scheduler.c</code>。</p><h2 id="就緒佇列" tabindex="-1">就緒佇列 <a class="header-anchor" href="#就緒佇列" aria-label="Permalink to &quot;就緒佇列&quot;">​</a></h2><p>FIFO（先進先出）把新就緒的 PCB 放到隊尾，從隊首取出下一個。佇列以 PCB 裡的 <code>ready_next</code> 串接，不複製 PCB。</p><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/scheduler.c" target="_blank" rel="noreferrer">kernel/scheduler.c（GitHub）</a>。</p><p>有 head（隊首）和 tail（隊尾）指標，因此入列與取隊首是 O(1)。移除特定行程要從隊首尋找前一節點，最壞 O(N)。<code>ready_queued</code> 避免重複入列。</p><h2 id="什麼時候會換人" tabindex="-1">什麼時候會換人 <a class="header-anchor" href="#什麼時候會換人" aria-label="Permalink to &quot;什麼時候會換人&quot;">​</a></h2><p><code>process.c</code> 的 <code>transition</code> 維護狀態與佇列。進入 Ready 排到隊尾，離開 Ready 就移除；Running、Waiting、Zombie 不應留在佇列中。</p><p><code>process_resume</code> 先檢查原行程是否仍是 Running。如果是，就繼續原行程；否則才從 FIFO 取下一個。普通 syscall 不會自動讓出 CPU，只有 yield、阻塞、退出等情況觸發選擇。</p><p>因此這是 cooperative scheduling（合作式排程）。不是 RR（輪詢時間片排程）：目前沒有計時器在時間片結束時強制切換。</p><h2 id="切換時-cpu-改變什麼" tabindex="-1">切換時 CPU 改變什麼 <a class="header-anchor" href="#切換時-cpu-改變什麼" aria-label="Permalink to &quot;切換時 CPU 改變什麼&quot;">​</a></h2><p>核心選中 PCB 後切換 satp（分頁設定暫存器）指向它的頁表，並把它的 TrapFrame 交給 <code>trap.S</code>。暫存器與 sepc 恢復後，CPU 從該行程保存的位置繼續執行。</p><p>這裡不保存可長期暫停的 C 核心呼叫堆疊；待完成操作改記錄在 PCB。I/O 補完後設定返回結果，再讓行程回到 Ready。</p><h2 id="在-qemu-觀察" tabindex="-1">在 QEMU 觀察 <a class="header-anchor" href="#在-qemu-觀察" aria-label="Permalink to &quot;在 QEMU 觀察&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run counter</span></span>
<span class="line"><span>run counter</span></span>
<span class="line"><span>ps</span></span>
<span class="line"><span>wakeup 9</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>兩個 counter 等待通道 9。喚醒後各自從 3 倒數，每印一次就 yield，所以可看到交替；依輸出的 PID 分別 <code>wait</code> 回收。<code>ps</code> 額外列出 Ready queue，但行程可能在下一次輸入前已完成。</p><h2 id="與記憶體-fifo-的區別" tabindex="-1">與記憶體 FIFO 的區別 <a class="header-anchor" href="#與記憶體-fifo-的區別" aria-label="Permalink to &quot;與記憶體 FIFO 的區別&quot;">​</a></h2><p>這一章 FIFO 決定誰取得 CPU；<a href="./paging.html">頁面置換 FIFO</a> 決定誰讓出實體頁框。兩者管理不同資源，資料結構也不相同。</p><p>觀念參考：<code>notes/ch5 CPU schedueling.md</code> 的 FCFS 與非搶占排程。WUWAOS 保留主動 yield，實作與既有驗收見 <a href="./../SPEC-07-fifo-scheduler.html">Spec 07</a>。</p>`,19)])])}const m=a(t,[["render",o]]);export{u as __pageData,m as default};
